@Composable
fun StreaksScreen() {
 val days = listOf("S", "S", "M", "T", "W", "T", "F")

 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(vertical = 60.dp, horizontal = 24.dp),
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.Top
 ) {

 Box(
 modifier = Modifier
 .size(350.dp)
 .clip(CircleShape),
 ) {

 LifecycleAwareLottieView(
 resId = R.raw.streak,
 modifier = Modifier.fillMaxSize(),
 alignment = Alignment.Center
 )

 Text(
 modifier = Modifier
 .align(Alignment.BottomCenter)
 .padding(bottom = 40.dp),
 text = stringResource(R.string.number_10),
 color = Color.White,
 fontSize = 64.sp,
 fontWeight = FontWeight.ExtraBold
 )
 }

 Spacer(modifier = Modifier.height(32.dp))

 Row(
 horizontalArrangement = Arrangement.spacedBy(12.dp),
 verticalAlignment = Alignment.CenterVertically
 ) {
 days.forEach {
 Box(
 modifier = Modifier
 .size(36.dp)
 .clip(CircleShape)
 .background(MaterialTheme.colorScheme.primary),
 contentAlignment = Alignment.Center
 ) {
 Text(
 text = it,
 color = Color.White,
 fontWeight = FontWeight.Bold
 )
 }
 }
 }

 Spacer(modifier = Modifier.height(32.dp))

 Text(
 text = stringResource(R.string.txt_ten_day_streak),
 fontSize = 30.sp,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.onBackground,
 textAlign = TextAlign.Center
 )

 Spacer(modifier = Modifier.height(8.dp))

 Text(
 text = stringResource(R.string.txt_streak_description),
 fontSize = 18.sp,
 color = MaterialTheme.colorScheme.onSurface,
 textAlign = TextAlign.Center,
 modifier = Modifier.padding(horizontal = 16.dp)
 )
 }
}"},{"role":"tool","name":"read_file","tool_call_id":"toolu_bdrk_01FnL3hekYYFYqrho4EXmomi","content":"package com.roque.epicmedalsapp.ui.navigation

